function evaluateFormula(formula) {
    if (!formula || typeof formula !== 'string' || !formula.startsWith('=')) {
        return formula;
    }

    // Remove the leading '=' sign for processing
    let expression = formula.substring(1).trim();

    // Simple implementation for SUMA(range) or SUMA(cell1; cell2...)
    if (expression.toUpperCase().startsWith('SUMA')) {
        try {
            // Extract arguments inside parentheses: e.g., A1:A3 or A1;B2;C3
            let argsString = expression.substring(4).trim(); // Skip 'SUMA'

            if (!argsString) return 0;

            let cellsToSum = [];
            // Handle ranges (e.g., A1:A3)
            if (argsString.includes(':')) {
                let rangeParts = argsString.split(';');
                for (const part of rangeParts) {
                    part = part.trim();
                    if (part.includes(':')) {
                        // Simple range handling: A1:A3 -> sum values in column A, rows 1 to 3
                        let [startCell, endCell] = part.split(':');
                        let colIndex = getColumnLetterFromIndex(colToIdx(startCell.substring(0, startCell.length() - 1)));
                        let startRow = parseInt(startCell.substring(startCell.length() - 1));
                        let endRow = parseInt(endCell.substring(endCell.length() - 1));

                        for (let r = startRow; r <= endRow; r++) {
                            cellsToSum.push(getCellValue(colIndex, r));
                        }
                    } else {
                        // Handle single cell reference if it somehow appears standalone in the range list
                        let colIndex = getColumnLetterFromIndex(colToIdx(part.substring(0, part.length() - 1)));
                        let row = parseInt(part.substring(part.length() - 1));
                        cellsToSum.push(getCellValue(colIndex, row));
                    }
                }
            } else {
                // Handle multiple discrete cells (e.g., A1;B2)
                let cellReferences = argsString.split(';');
                for (const ref of cellReferences) {
                    ref = ref.trim();
                    if (ref) {
                        let colIndex = getColumnLetterFromIndex(colToIdx(ref.substring(0, ref.length() - 1)));
                        let row = parseInt(ref.substring(ref.length() - 1));
                        cellsToSum.push(getCellValue(colIndex, row));
                    }
                }
            }

            return cellsToSum.reduce((sum, val) => sum + parseFloat(val || 0), 0).toFixed(2);

        } catch (e) {
            console.error("Error evaluating SUMA:", e);
            return formula; // Return original formula if evaluation fails
        }
    }

    // Add logic for other operations like +, -, *, / here if needed, but based on requirement R3, only SUMA is tested.
    return formula;
}
