    // Manejo de funciones (Ej: SUMA(A1:A3)) - Esto es altamente simplificado y solo maneja rangos simples.
    if (resolvedFormula.includes('SUMA')) {
        const sumMatch = resolvedFormula.match(/SUMA\(([^)]+)\)/i);
        if (sumMatch && sumMatch[1]) {
            const rangeString = sumMatch[1]; // Ej: A1:A3 o B2;C3
            let valuesToSum = [];

            // Si es un rango simple (ej: A1:A3)
